"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["78943"],{66531(e){e.exports=JSON.parse('{"id":"FIN-403","slug":"trailing-p-e","term":"Trailing P/E","also_known_as":[],"difficulty":"Intermediate","definition":"Trailing P/E is a company\'s current share price divided by its earnings per share over the past twelve months.","explanation":["The trailing P/E uses actual, reported earnings rather than forecasts. It is the most common version of the price-to-earnings ratio quoted in financial news and data services.","For example, if a share trades at 45 and the company\'s earnings per share over the last four quarters add up to 3, the trailing P/E is 15.","The main strength of trailing P/E is that it is based on real results, not estimates, so it is objective and easy to verify.","Its main weakness is that it looks backwards. If a company\'s earnings are growing quickly, the trailing P/E may make the shares look more expensive than they really are compared with future earnings. If earnings are about to fall, it may make them look cheaper than they are. One-off gains or losses in the past year can also distort it.","Investors often look at trailing P/E alongside forward P/E, which uses expected earnings, to get a balanced picture of a company\'s valuation."],"note":"","total":1725,"prev":{"slug":"tragedy-of-the-commons","term":"Tragedy of the Commons"},"next":{"slug":"tranche","term":"Tranche"}}')}}]);